const content = $json.choices[0].message.content;
const parsed = typeof content === 'string' ? JSON.parse(content) : content;
return {
  json: {
    campaign_id: $('Get Campaign').item.json.id,
    search_params: parsed
  }
};

const inputItems = $input.all();
let profiles = [];
for (const it of inputItems) {
  if (Array.isArray(it.json)) {
    profiles.push(...it.json);
  } else {
    profiles.push(it.json);
  }
}

const campaignId = $('Parse Search Params').first().json.campaign_id;

function extractLocation(p) {
  if (!p.location) return null;
  if (typeof p.location === 'string') return p.location;
  return p.location.linkedinText || (p.location.parsed && p.location.parsed.text) || null;
}

return profiles.map(p => ({
  json: {
    campaign_id: campaignId,
    linkedin_url: p.linkedinUrl || p.profileUrl || p.publicIdentifier || p.url || '',
    full_name: p.fullName || [p.firstName, p.lastName].filter(Boolean).join(' ') || null,
    headline: p.headline || null,
    location: extractLocation(p),
    source: 'apify',
    raw_data: p
  }
}));
